(()=>{'use strict';
if(window.__OBRIX_CORRECOES_REAIS_20261102)return;window.__OBRIX_CORRECOES_REAIS_20261102=true;
let obraChecklistId='',filaVisual=false,saveTimer=null,refreshTimer=null,canal=null,retryTimer=null,ctxCache=null,finObs=null;
const estilo=document.createElement('style');estilo.id='obrix-correcoes-reais-20261102-style';estilo.textContent=`@media(max-width:760px){#fmFiltrosPanel .fmFiltrosGrid label.obrixDataFull{grid-column:1/-1!important;min-width:0!important}#fmFiltroDataInicio,#fmFiltroDataFim{display:block!important;width:100%!important;max-width:100%!important;min-width:0!important;box-sizing:border-box!important;font-size:14px!important;padding-left:10px!important;padding-right:10px!important}}`;
function estiloPorUltimo(){if(estilo.parentNode!==document.head||document.head.lastElementChild!==estilo)document.head.appendChild(estilo)}
function brancoAndamento(){document.querySelectorAll('#obras .obxStatus-andamento,#listaObras .obxStatus-andamento').forEach(el=>{el.style.setProperty('color','#fff','important');el.style.setProperty('-webkit-text-fill-color','#fff','important')})}
function corrigirDatas(){if(innerWidth>760)return;for(const id of ['fmFiltroDataInicio','fmFiltroDataFim']){const el=document.getElementById(id);if(!el)continue;const lab=el.closest('label');lab?.classList.add('obrixDataFull');el.style.setProperty('width','100%','important');el.style.setProperty('max-width','100%','important');el.style.setProperty('min-width','0','important');el.style.setProperty('box-sizing','border-box','important')}}
function detectarObraModal(){if(!document.querySelector('.checkModalBack')){obraChecklistId='';return}if(obraChecklistId)return;const nome=document.querySelector('.checkModalBack .checkHead .muted')?.textContent?.trim();if(!nome)return;const o=(window.obras||[]).find(x=>String(x.nome||'').trim()===nome);if(o)obraChecklistId=String(o.id)}
function aplicarVisuais(){filaVisual=false;estiloPorUltimo();brancoAndamento();corrigirDatas();detectarObraModal()}
function agendarVisuais(){if(filaVisual)return;filaVisual=true;requestAnimationFrame(aplicarVisuais)}
function capturarObraChecklist(alvo){const card=alvo?.closest?.('.obxObraCard[data-obra-id]');if(card&&alvo.closest?.('.obxChecklist')){obraChecklistId=String(card.dataset.obraId||'');return}const b=alvo?.closest?.('[data-check-open]');if(b?.dataset?.checkOpen)obraChecklistId=String(b.dataset.checkOpen)}
function mediaAtual(){const ranges=[...document.querySelectorAll('.checkModalBack [data-check-range]')];if(!ranges.length)return null;const soma=ranges.reduce((s,r)=>s+Math.max(0,Math.min(100,Number(r.value||0))),0);return Math.round((soma/ranges.length)*10)/10}
function aplicarProgressoLocal(id,p){if(!id||p==null)return;const o=(window.obras||[]).find(x=>String(x.id)===String(id));if(o)o.progresso=p;try{window.OBRIX_OBRAS?.render?.()}catch(_){}try{window.OBRIX_DASH?.paint?.()}catch(_){}agendarVisuais()}
async function contexto(){if(ctxCache)return ctxCache;const p=await window.OBRIX_BACKEND?.profile?.();if(!p?.empresa_id)return null;ctxCache={sb:await window.OBRIX_BACKEND.init(),eid:p.empresa_id};return ctxCache}
async function atualizarDados(){if(!navigator.onLine||document.hidden)return;try{if(typeof window.carregar==='function')await window.carregar();else if(typeof window.OBRIX_REFRESH_ALL==='function')await window.OBRIX_REFRESH_ALL();try{await window.OBRIX_FIN?.render?.(true)}catch(_){}try{await window.OBRIX_EQUIPE?.refresh?.()}catch(_){}try{window.OBRIX_OBRAS?.render?.()}catch(_){}try{window.OBRIX_DASH?.paint?.()}catch(_){}}catch(e){console.warn('OBRIX: sincronização será repetida',e)}finally{agendarVisuais()}}
function agendarDados(ms=220){clearTimeout(refreshTimer);refreshTimer=setTimeout(atualizarDados,ms)}
async function salvarProgresso(){detectarObraModal();const id=obraChecklistId,p=mediaAtual();if(!id||p==null||!navigator.onLine)return;aplicarProgressoLocal(id,p);try{const c=await contexto();if(!c)return;const r=await c.sb.from('obras').update({progresso:p}).eq('empresa_id',c.eid).eq('id',id);if(r.error)throw r.error;agendarDados(80)}catch(e){console.warn('OBRIX: não foi possível salvar o progresso geral agora',e)}}
function agendarSalvar(){clearTimeout(saveTimer);saveTimer=setTimeout(salvarProgresso,650)}
function acompanharFinanceiro(){const form=document.getElementById('fmForm');if(!form||finObs)return;finObs=new MutationObserver(()=>{if(!form.classList.contains('hidden'))return;finObs.disconnect();finObs=null;agendarDados(80)});finObs.observe(form,{attributes:true,attributeFilter:['class']});setTimeout(()=>{if(finObs){finObs.disconnect();finObs=null}},8000)}
function pararCanal(){clearTimeout(retryTimer);retryTimer=null;if(canal){try{canal.unsubscribe?.()}catch(_){}canal=null}}
async function realtime(){if(canal||!navigator.onLine)return;try{const c=await contexto();if(!c)return;let ch=c.sb.channel('obrix-sync-real-'+c.eid);
ch=ch.on('postgres_changes',{event:'*',schema:'public',table:'obras',filter:`empresa_id=eq.${c.eid}`},payload=>{const novo=payload?.new;if(novo?.id){const o=(window.obras||[]).find(x=>String(x.id)===String(novo.id));if(o)Object.assign(o,novo);try{window.OBRIX_OBRAS?.render?.()}catch(_){}try{window.OBRIX_DASH?.paint?.()}catch(_){}agendarVisuais()}else agendarDados(100)});
for(const tabela of ['financeiro','funcionarios','diarias','vales','bonus_extras','servicos_extras','checklist_itens'])ch=ch.on('postgres_changes',{event:'*',schema:'public',table:tabela,filter:`empresa_id=eq.${c.eid}`},()=>agendarDados(160));
canal=ch.subscribe(status=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED'){pararCanal();retryTimer=setTimeout(realtime,1500)}})}catch(e){console.warn('OBRIX: realtime indisponível',e);pararCanal();retryTimer=setTimeout(realtime,1800)}}
document.addEventListener('click',e=>{capturarObraChecklist(e.target);if(e.target.closest?.('#fmSalvar'))acompanharFinanceiro();setTimeout(agendarVisuais,0);setTimeout(agendarVisuais,160)},true);
document.addEventListener('input',e=>{if(!e.target.closest?.('[data-check-range]'))return;detectarObraModal();const p=mediaAtual();if(obraChecklistId&&p!=null)aplicarProgressoLocal(obraChecklistId,p)},true);
document.addEventListener('change',e=>{if(!e.target.closest?.('[data-check-range]'))return;detectarObraModal();const p=mediaAtual();if(obraChecklistId&&p!=null)aplicarProgressoLocal(obraChecklistId,p);agendarSalvar()},true);
const root=document.getElementById('app')||document.body;new MutationObserver(agendarVisuais).observe(root,{childList:true,subtree:true});
window.addEventListener('focus',()=>{agendarVisuais();agendarDados(100);realtime()});window.addEventListener('pageshow',()=>{agendarVisuais();agendarDados(100);realtime()});document.addEventListener('visibilitychange',()=>{if(!document.hidden){agendarVisuais();agendarDados(100);realtime()}});window.addEventListener('online',()=>{pararCanal();agendarDados(80);realtime()});window.addEventListener('offline',pararCanal);window.addEventListener('resize',agendarVisuais);
setTimeout(()=>{agendarVisuais();realtime()},300);setTimeout(agendarVisuais,1000);
})();